const MAX_BYTES = 5 * 1024 * 1024;
const salida = [];

for (const item of $input.all()) {
  const h = item.json.headers || {};
  const asunto = (h.subject || '').replace(/^Subject:\s*/i, '').trim();
  const from = h.from || '';
  const bin = item.binary || {};
  const adjuntos = Object.keys(bin);

  const emailMatch = from.match(/<([^>]+)>/);
  const email_remitente = (emailMatch ? emailMatch[1] : from).toLowerCase().trim();

  let codigo = null;
  let motivo = null;
  let cuit_asunto = null;
  let numero_factura = null;

  const m = asunto.match(/^FACTURA - (\d{11}) - ([ABC])(\d{5})(\d{8})$/);
  if (!m) {
    codigo = 'RC-02';
    motivo = 'Asunto con formato invalido';
  } else {
    cuit_asunto = m[1];
    numero_factura = m[2] + m[3] + m[4];
  }

  if (!codigo && adjuntos.length === 0) {
    codigo = 'RC-03';
    motivo = 'Correo sin adjunto';
  }

  if (!codigo && adjuntos.length > 1) {
    codigo = 'RC-04';
    motivo = 'Mas de un adjunto en el mismo correo';
  }

  if (!codigo) {
    const a = bin[adjuntos[0]];
    const nombre = (a.fileName || '').toLowerCase();
    const esPdf = a.mimeType === 'application/pdf' || nombre.endsWith('.pdf');
    if (!esPdf) {
      codigo = 'RC-05';
      motivo = 'Formato de archivo no admitido';
    } else {
      const bytes = a.data
        ? Math.floor(a.data.length * 0.75)
        : Number(item.json.sizeEstimate || 0);
      if (bytes > MAX_BYTES) {
        codigo = 'RC-07';
        motivo = 'Archivo que excede el tamano maximo';
      }
    }
  }

  salida.push({
    json: {
      gmail_id: item.json.id,
      email_remitente,
      asunto,
      cuit_asunto,
      numero_factura,
      adjunto_key: adjuntos[0] || null,
      rechazado: codigo !== null,
      codigo_rechazo: codigo,
      motivo_rechazo: motivo,
    },
    binary: item.binary,
  });
}

return salida;

const sobre = $('Validaciones de sobre').first();
const encontrados = $input.all();

const hayProveedor = encontrados.length > 0 && encontrados[0].json.id;
const p = hayProveedor ? encontrados[0].json.fields : {};

let codigo = null;
let motivo = null;

if (!hayProveedor) {
  codigo = 'RC-01';
  motivo = 'CUIT no registrado en el legajo de proveedores';
}

return [{
  json: {
    ...sobre.json,
    proveedor_id: hayProveedor ? encontrados[0].json.id : null,
    razon_social: p.razon_social || null,
    plazo_pago_dias: p.plazo_pago_dias || null,
    monto_max_auto: p.monto_max_auto || null,
    rechazado: sobre.json.rechazado === true || codigo !== null,
    codigo_rechazo: sobre.json.codigo_rechazo || codigo,
    motivo_rechazo: sobre.json.motivo_rechazo || motivo,
  },
  binary: sobre.binary,
}];

const ctx = $('Armar contexto').first();
const pdf = $input.first().json;
const texto = (pdf.text || '').trim();

let codigo = null;
let motivo = null;

if (texto.length < 50) {
  codigo = 'RC-06';
  motivo = 'PDF sin texto seleccionable';
}

return [{
  json: {
    ...ctx.json,
    texto_pdf: texto,
    paginas_pdf: pdf.numpages || null,
    rechazado: ctx.json.rechazado === true || codigo !== null,
    codigo_rechazo: ctx.json.codigo_rechazo || codigo,
    motivo_rechazo: ctx.json.motivo_rechazo || motivo,
  },
  binary: ctx.binary,
}];

const ctx = $('Validar texto PDF').first();
const crudo = $input.first().json.text || '';

let ia = null;
let codigo = null;
let motivo = null;
let discrepancias = [];

try {
  let limpio = crudo.replace(/```json/gi, '').replace(/```/g, '').trim();
  const desde = limpio.indexOf('{');
  const hasta = limpio.lastIndexOf('}');
  if (desde !== -1 && hasta !== -1) limpio = limpio.slice(desde, hasta + 1);
  limpio = limpio.replace(/:(\s*)(-?\d+(?:\.\d+)?)"/g, ':$1$2');
  ia = JSON.parse(limpio);
} catch (e) {
  return [{
    json: {
      ...ctx.json,
      rechazado: ctx.json.rechazado === true,
      requiere_revision: ctx.json.rechazado !== true,
      codigo_rechazo: ctx.json.codigo_rechazo || null,
      motivo_rechazo: ctx.json.motivo_rechazo || 'La IA devolvio una respuesta no parseable',
      confianza_ia: 0,
      supera_tope: false,
      confianza_baja: true,
      discrepancias: 'La IA devolvio una respuesta no parseable',
    },
    binary: ctx.binary,
  }];
}

const neto = Number(ia.neto) || 0;
const iva = Number(ia.iva) || 0;
const total = Number(ia.total) || 0;
const confianza = Number(ia.confianza ?? ia.confidence) || 0;

const suma = Math.round((neto + iva) * 100) / 100;
const totalRedondeado = Math.round(total * 100) / 100;

if (Math.abs(suma - totalRedondeado) > 0.01) {
  codigo = 'RC-09';
  motivo = 'Inconsistencia entre neto, IVA y total';
  discrepancias.push(
    `Neto ${neto} + IVA ${iva} = ${suma}, pero el total impreso es ${totalRedondeado}`
  );
}

const cuitIA = String(ia.cuit_emisor || '').replace(/\D/g, '');
if (!codigo && cuitIA !== ctx.json.cuit_asunto) {
  codigo = 'RC-10';
  motivo = 'CUIT del emisor no coincide con el asunto';
  discrepancias.push(
    `CUIT en el PDF: ${cuitIA}, CUIT en el asunto: ${ctx.json.cuit_asunto}`
  );
}

let vencimiento = null;
if (ia.fecha_emision && ctx.json.plazo_pago_dias) {
  const d = new Date(ia.fecha_emision + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + Number(ctx.json.plazo_pago_dias));
  const dia = d.getUTCDay();
  if (dia === 6) d.setUTCDate(d.getUTCDate() + 2);
  if (dia === 0) d.setUTCDate(d.getUTCDate() + 1);
  vencimiento = d.toISOString().slice(0, 10);
}

const superaTope =
  ctx.json.monto_max_auto !== null && total > Number(ctx.json.monto_max_auto);

if (superaTope) {
  discrepancias.push(
    `Total ${total} supera el tope automatico de ${ctx.json.monto_max_auto}`
  );
}

const confianzaBaja = confianza < 0.7;
if (confianzaBaja) {
  discrepancias.push(`Confianza de lectura baja: ${confianza}`);
}

const rechazadoFinal = ctx.json.rechazado === true || codigo !== null;

return [{
  json: {
    ...ctx.json,
    cuit_emisor: cuitIA || null,
    razon_social_emisor: ia.razon_social_emisor || null,
    fecha_emision: ia.fecha_emision || null,
    fecha_vencimiento: vencimiento,
    neto,
    iva,
    total,
    confianza_ia: confianza,
    rechazado: rechazadoFinal,
    codigo_rechazo: ctx.json.codigo_rechazo || codigo,
    motivo_rechazo: ctx.json.motivo_rechazo || motivo,
    requiere_revision: !rechazadoFinal && (superaTope || confianzaBaja),
    supera_tope: superaTope,
    confianza_baja: confianzaBaja,
    discrepancias: discrepancias.join(' | '),
  },
  binary: ctx.binary,
}];

